<?php $pageTitle='Edit T-shirt';require '../includes/admin-header.php';$pdo=db();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)go('admin/products.php');$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$sq=$pdo->prepare('SELECT size,stock_quantity FROM product_sizes WHERE product_id=?');$sq->execute([$id]);$stocks=array_column($sq->fetchAll(),'stock_quantity','size');if($_SERVER['REQUEST_METHOD']==='POST'){$stock=array_sum(array_map('intval',$_POST['size_stock']));$pdo->prepare('UPDATE products SET category_id=?,name=?,brand=?,description=?,material=?,fit_type=?,color=?,original_price=?,discount_percent=?,stock_quantity=?,status=? WHERE id=?')->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['brand']),trim($_POST['description']),trim($_POST['material']),trim($_POST['fit_type']),trim($_POST['color']),(float)$_POST['original_price'],(float)$_POST['discount_percent'],$stock,$_POST['status'],$id]);$s=$pdo->prepare('UPDATE product_sizes SET stock_quantity=? WHERE product_id=? AND size=?');foreach($_POST['size_stock'] as $size=>$qty)$s->execute([(int)$qty,$id,$size]);flash('success','T-shirt updated.');go('admin/products.php');} ?><form method="post" class="card card-body"><div class="row g-3"><div class="col-md-6"><label>Product name</label><input class="form-control" name="name" value="<?=e($p['name'])?>"></div><div class="col-md-3"><label>Brand</label><input class="form-control" name="brand" value="<?=e($p['brand'])?>"></div><div class="col-md-3"><label>Collection</label><select class="form-select" name="category_id"><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select></div><div class="col-12"><label>Description</label><textarea class="form-control" name="description"><?=e($p['description'])?></textarea></div><div class="col-md-4"><label>Material</label><input class="form-control" name="material" value="<?=e($p['material'])?>"></div><div class="col-md-4"><label>Fit</label><input class="form-control" name="fit_type" value="<?=e($p['fit_type'])?>"></div><div class="col-md-4"><label>Colour</label><input class="form-control" name="color" value="<?=e($p['color'])?>"></div><div class="col-md-3"><label>Price</label><input class="form-control" name="original_price" value="<?=$p['original_price']?>"></div><div class="col-md-3"><label>Discount %</label><input class="form-control" name="discount_percent" value="<?=$p['discount_percent']?>"></div><div class="col-md-3"><label>Status</label><select class="form-select" name="status"><?php foreach(['active'=>'Active','inactive'=>'Inactive','out_of_stock'=>'Out of Stock'] as $v=>$l): ?><option value="<?=$v?>" <?=$p['status']===$v?'selected':''?>><?=$l?></option><?php endforeach ?></select></div><div class="col-12"><b>Stock by size</b><div class="row mt-1"><?php foreach(['S','M','L','XL','XXL','XXXL'] as $s): ?><div class="col"><label><?=$s?></label><input class="form-control" type="number" min="0" name="size_stock[<?=$s?>]" value="<?=$stocks[$s]??0?>"></div><?php endforeach ?></div></div><div><button class="btn btn-dark">Save changes</button></div></div></form><?php require '../includes/admin-footer.php'; ?>
